.order-step{margin-bottom:20px}.step-number{float:left;width:27px;height:27px;margin-right:9px;display:grid;place-items:center;border-radius:50%;background:#171717;color:#fff;font-size:.75rem;font-weight:800}.order-type-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;padding:20px 22px 0}.order-type-option{display:flex;gap:12px;align-items:flex-start;padding:17px;border:1px solid #e3e3e0;border-radius:12px;cursor:pointer;transition:border-color .15s ease,box-shadow .15s ease,transform .15s ease}.order-type-option:hover{transform:translateY(-1px)}.order-type-option:has(input:checked){border-color:#171717;box-shadow:0 0 0 2px rgba(23,23,23,.08)}.order-type-option input{margin-top:4px}.order-type-option strong,.order-type-option small{display:block}.order-type-option small{color:#777;margin-top:4px}.table-field{padding:0 22px;margin-top:18px}.table-field label>span{display:block;margin-bottom:7px;font-weight:750}.table-field select{width:100%;padding:11px 12px;border:1px solid #d6d6d3;border-radius:9px;background:#fff}.order-toolbar{display:flex;align-items:center;justify-content:space-between;gap:18px}.product-tools{display:flex;gap:8px}.product-tools input,.product-tools select{min-height:38px;padding:8px 10px;border:1px solid #d6d6d3;border-radius:8px;background:#fff}.product-tools input{width:220px}.manual-product-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;padding:20px 22px}.manual-product-card{border:1px solid #e5e5e2;border-radius:12px;padding:16px;display:flex;flex-direction:column;justify-content:space-between;gap:18px;min-height:190px;transition:border-color .15s ease,box-shadow .15s ease,transform .15s ease}.manual-product-card.is-selected{border-color:#777;box-shadow:0 7px 22px rgba(0,0,0,.07);transform:translateY(-1px)}.manual-product-card[hidden]{display:none}.manual-product-card h3{margin:5px 0 6px;font-size:1rem}.manual-product-card p{color:#777;font-size:.86rem;margin:0}.manual-product-bottom{display:flex;justify-content:space-between;align-items:center;gap:10px}.qty-control{display:flex;align-items:center;border:1px solid #d1d1ce;border-radius:9px;overflow:hidden}.qty-control button{border:0;background:#f3f3f1;width:35px;height:35px;font-size:20px}.qty-control button:hover{background:#e9e9e6}.qty-control input{border:0;text-align:center;width:38px;height:35px;background:#fff}.manual-order-summary{margin:0 22px 20px;padding:16px;background:#f8f8f6;border:1px solid #e7e7e4;border-radius:12px}.summary-line{display:flex;justify-content:space-between;gap:12px;padding:7px 0}.summary-total{display:flex;justify-content:space-between;border-top:1px solid #ddd;margin-top:8px;padding-top:13px;font-size:1.12rem}.manual-order-form>section:last-child{padding-bottom:22px}.manual-order-form>section:last-child>label{display:block;margin:20px 22px 0;font-weight:750}.manual-order-form>section:last-child>label>span{display:block;margin-bottom:7px}.manual-order-form textarea{display:block}.manual-order-form .form-actions{padding:0 22px}.manual-order-summary p{margin:0;color:#777}.products-empty{padding:25px}@media(max-width:900px){.manual-product-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.order-toolbar{align-items:stretch;flex-direction:column}.product-tools input{flex:1;width:auto}}@media(min-width:901px){.manual-order-form>section:last-child{position:sticky;bottom:12px;z-index:10;box-shadow:0 14px 36px rgba(0,0,0,.08)}}@media(max-width:600px){.order-type-grid,.manual-product-grid{grid-template-columns:1fr}.product-tools{flex-direction:column}.product-tools input,.product-tools select{width:100%}.manual-order-form .form-actions{display:grid;grid-template-columns:1fr 1.4fr}.manual-order-form .form-actions .button{width:100%}}
</style>
<script>
const form=document.getElementById('manual-order-form'),tableField=document.getElementById('table-field'),tableSelect=document.getElementById('table_id'),summary=document.getElementById('order-summary'),submit=document.getElementById('submit-order'),count=document.getElementById('items-count'),search=document.getElementById('product-search'),category=document.getElementById('category-filter'),empty=document.getElementById('products-empty');
const money=v=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(v);
function refreshSummary(){let total=0,units=0,lines=[];document.querySelectorAll('.qty-control input').forEach(input=>{const qty=Number(input.value)||0;input.closest('.manual-product-card')?.classList.toggle('is-selected',qty>0);if(qty>0){const subtotal=qty*Number(input.dataset.price);total+=subtotal;units+=qty;lines.push(`<div class="summary-line"><span>${qty}× ${input.dataset.name}</span><strong>${money(subtotal)}</strong></div>`);}});count.textContent=`${units} ${units===1?'producto':'productos'} seleccionado${units===1?'':'s'}`;submit.disabled=units===0;summary.innerHTML=units===0?'<p>Agrega productos para ver el resumen.</p>':`${lines.join('')}<div class="summary-total"><strong>Total</strong><strong>${money(total)}</strong></div>`;}
function filterProducts(){const q=search.value.trim().toLowerCase(),cat=category.value;let shown=0;document.querySelectorAll('.manual-product-card').forEach(card=>{const hit=(!q||card.dataset.name.includes(q))&&(!cat||card.dataset.category===cat);card.hidden=!hit;if(hit)shown++;});empty.hidden=shown!==0;}
document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>{const input=document.querySelector(`input[name="items[${button.dataset.id}]"]`);let value=Number(input.value)||0;value=button.dataset.action==='plus'?Math.min(99,value+1):Math.max(0,value-1);input.value=value;refreshSummary();}));
document.querySelectorAll('input[name="type"]').forEach(radio=>radio.addEventListener('change',()=>{const isTable=document.querySelector('input[name="type"]:checked').value==='MESA';tableField.hidden=!isTable;if(!isTable)tableSelect.value='';}));search.addEventListener('input',filterProducts);category.addEventListener('change',filterProducts);form.addEventListener('submit',()=>{submit.disabled=true;submit.textContent='Creando pedido...'});tableField.hidden=document.querySelector('input[name="type"]:checked').value!=='MESA';refreshSummary();filterProducts();
</script>
